import { create } from 'zustand';
import { invoke } from '@tauri-apps/api/core';
import type { AppConfig } from '../config/UnifiedConfig';
import { defaultConfig } from '../config/UnifiedConfig';

interface ConfigState {
  config: AppConfig;
  isLoading: boolean;
  error: string | null;
  loadConfig: () => Promise<void>;
  updateConfig: (updater: (config: AppConfig) => void) => Promise<void>;
  previewBrightness: (displayId: string, target: number) => Promise<void>;
  lockCurrentComfort: (displayId: string, profileName: string) => Promise<void>;
}

export const useConfigStore = create<ConfigState>((set, get) => ({
  config: defaultConfig,
  isLoading: true,
  error: null,
  
  loadConfig: async () => {
    try {
      set({ isLoading: true, error: null });
      const backendConfig = await invoke<AppConfig>('get_config');
      set({ config: backendConfig, isLoading: false });
    } catch (e) {
      console.error('Failed to load config:', e);
      set({ error: String(e), isLoading: false });
    }
  },

  updateConfig: async (updater) => {
    try {
      const currentConfig = JSON.parse(JSON.stringify(get().config));
      updater(currentConfig);
      
      // Update local working copy immediately for UI responsiveness
      set({ config: currentConfig });
      
      // Push to authoritative Rust backend
      await invoke('save_config', { newConfig: currentConfig });
    } catch (e) {
      console.error('Failed to save config:', e);
      set({ error: String(e) });
    }
  },

  lockCurrentComfort: async (displayId: string, profileName: string) => {
    try {
      await invoke('lock_current_comfort', { displayId, profileName });
    } catch (e) {
      console.error('Failed to lock comfort:', e);
      throw e;
    }
  },

  previewBrightness: async (displayId: string, target: number) => {
    try {
      await invoke('preview_brightness', { displayId, target });
    } catch (e) {
      console.error('Failed to preview brightness:', e);
    }
  }
}));

